import {PolicyPage,PolicySection} from '@/components/PolicyPage';

const sections:PolicySection[]=[
 {heading:'1. Scope and Controller',paragraphs:['This Policy applies to personal data processed through CDA Connect for users in Nigeria and other individuals protected by applicable law. CDA Connect acts as controller for core account and platform operations.','A community may separately act as controller for information it collects or decides to use through its workspace. Questions and data requests may be sent to support@cdaconnect.org.']},
 {heading:'2. Applicable Privacy Rules',paragraphs:['We intend to process personal data in accordance with the Nigeria Data Protection Act 2023 and the Nigeria Data Protection Act General Application and Implementation Directive 2025.','We also recognise the constitutional right to privacy and applicable sector, consumer-protection, communications, cybersecurity and child-safety requirements.']},
 {heading:'3. Information We Collect',paragraphs:['Account and identity data may include name, email, phone, date of birth, address, location area, profile image, verification status and account identifiers.','Community data may include memberships, roles, posts, comments, reactions, chat, events, meetings, attendance, votes, reports, documents, marketplace or service listings, and financial-record references.','Technical data may include device and browser type, IP-derived information, authentication sessions, security events, notification tokens, crash logs, timestamps and usage interactions.','Support and preference data includes support communications, language, accessibility, privacy, notification, communication and storage choices. Payment credentials are generally processed by payment providers rather than stored by CDA Connect unless expressly disclosed.']},
 {heading:'4. How We Obtain Information',paragraphs:['We receive information directly from you, from community administrators acting within their permissions, from your device when permissions are enabled, and from service providers used to operate the app.','Camera, media, location, calendar, notification or biometric capabilities are accessed only through supported device permissions and the feature you choose to use.']},
 {heading:'5. Purposes and Lawful Bases',paragraphs:['We process data to perform our contract with you: create accounts, provide communities, communication, events, documents, preferences and requested features.','We rely on legitimate interests where appropriate to secure the platform, prevent abuse, maintain reliability, understand feature performance and support users, after considering individual rights and reasonable expectations.','We process data to comply with legal obligations, respond to valid authorities, preserve required records and protect legal rights.','We seek consent where required, including for optional device permissions, certain communications or processing that cannot rely on another lawful basis. Consent can be withdrawn without affecting earlier lawful processing.','Vital interests or public-interest grounds may apply in limited emergencies or legally authorised circumstances.']},
 {heading:'6. Sensitive Personal Data',paragraphs:['Sensitive data receives additional protection. Do not post health, biometric, political, religious, sexual, genetic or other sensitive information unless necessary and lawful.','Device biometric templates remain controlled by the device operating system; CDA Connect uses protected device authentication and does not receive the underlying fingerprint or face template.']},
 {heading:'7. Visibility and Community Sharing',paragraphs:['Information is shown according to feature design, community membership, role permissions and your privacy choices. Posts or records shared with a community may be visible to its authorised members and administrators.','Community administrators must only access and use member information for legitimate community purposes and must not export, disclose or repurpose it unlawfully.','Before posting, consider whether information contains another person’s private data and obtain permission where required.']},
 {heading:'8. Service Providers and Recipients',paragraphs:['We may use vetted providers for hosting, storage, email, SMS, push notifications, analytics, security, customer support and payment processing. They receive only information reasonably needed for contracted services.','Information may be disclosed to professional advisers, auditors, insurers, corporate transaction participants or authorities where lawful and necessary. We do not sell personal data.','Payment providers and linked third-party services may act under their own privacy notices.']},
 {heading:'9. International Transfers',paragraphs:['Data may be processed outside Nigeria where infrastructure or providers operate internationally. We assess transfer conditions and use safeguards required by the NDP Act and GAID, such as adequacy, contractual protection, consent where valid, or another lawful transfer basis.','We apply confidentiality, security and purpose limitations to transferred information and assess relevant country and provider risks.']},
 {heading:'10. Retention',paragraphs:['Account data is generally retained while the account is active and for a reasonable period afterward where needed for restoration, disputes, fraud prevention, legal compliance or enforcement.','Security logs and session records are retained for periods proportionate to security risk. Support, moderation and transaction-related records may be retained for complaint, accounting or legal limitation periods.','Notifications and temporary cache follow the in-app retention controls where applicable. Backups expire on managed cycles. Data is deleted, anonymised or securely restricted when no longer required.']},
 {heading:'11. Security',paragraphs:['We use organisational and technical measures such as access controls, authentication, protected tokens, encryption where appropriate, logging, backups, role permissions and vulnerability management.','No system is perfectly secure. Protect credentials, use two-factor authentication where available and report suspicious activity promptly.','When a personal-data breach creates legally reportable risk, we will investigate, mitigate and notify the Nigeria Data Protection Commission and affected individuals within applicable requirements.']},
 {heading:'12. Your Data-Subject Rights',paragraphs:['Subject to lawful limits, you may request confirmation and access; correction; deletion; restriction; objection; data portability; and information about processing.','You may withdraw consent, object to certain direct marketing, and challenge a decision based solely on automated processing where it produces legal or similarly significant effects. CDA Connect does not intend to make such significant solely automated decisions without required safeguards.','We may verify identity before completing a request and may preserve information that lawfully must be retained. Requests should receive a response within the period required by applicable law.']},
 {heading:'13. Children and Vulnerable Users',paragraphs:['CDA Connect is not intended for unsupervised use by children who cannot validly consent under applicable law. A parent, guardian or appropriately authorised community must provide required permission and safeguards.','We apply heightened care to children’s data, avoid unnecessary profiling, and encourage guardians and administrators to follow Nigerian child-online-protection guidance.','Report suspected exploitation, grooming or child sexual abuse material immediately. We may preserve evidence and notify appropriate authorities where lawful.']},
 {heading:'14. Cookies, Local Storage and Notifications',paragraphs:['The web app may use necessary cookies or local storage for authentication, preferences, security and reliable operation. Optional analytics should be subject to applicable notice and consent requirements.','Push, email and SMS preferences can be managed in the app, except essential security, transactional or legally required communications.']},
 {heading:'15. Requests and Complaints',paragraphs:['Send privacy requests to support@cdaconnect.org with the subject “Privacy Request”. Do not send passwords, full payment credentials or verification codes.','If you are dissatisfied, you may complain to the Nigeria Data Protection Commission through its official channels. Consumer issues may also fall within FCCPC jurisdiction. These rights are not limited by this Policy.']},
 {heading:'16. Policy Updates',paragraphs:['We may update this Policy for changes in law, GAID guidance, technology or service operation. We will change the updated date and provide appropriate notice for material changes.','Where a new purpose requires consent or another action, we will obtain it before that processing begins.']},
];
export default function PrivacyPolicy(){return <PolicyPage intro="This Policy explains what personal data CDA Connect processes, why it is used, how it is protected, and the rights available under Nigerian data-protection law." sections={sections}/>}
